component.css:
.sb-root {
  --sb-ink: #E7DFC4;
  --sb-dim: #9A9179;
  --sb-gold: #CFC073;
  --sb-panel: #0D130E;
  --sb-panel2: #111813;

  position: relative;
  width: 100%;
  max-width: 340px;
  margin: 12px auto;
  aspect-ratio: 941 / 1672;
  container-type: inline-size;
  background: #060906 url("https://origin.picgo.net/2026/09/13/1000083554e7a3d49191a80db2.png") 50% 50% / 100% 100% no-repeat;
  border-radius: 20px;
  overflow: hidden;
  user-select: none;
  cursor: pointer;
  font-family: "Noto Serif SC", "Noto Serif CJK SC", "Source Han Serif SC", "Songti SC", "STSong", SimSun, serif;
  animation: sb-boot 0.55s ease-out both;
}

@keyframes sb-boot {
  from { opacity: 0; transform: scale(0.97); }
  to   { opacity: 1; transform: scale(1); }
}



.sb-val {
  position: absolute;
  top: 14.1%;
  height: 3.3%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--sb-panel);
  color: #D9D1B2;
  font-family: "Courier New", "SFMono-Regular", Menlo, Consolas, monospace;
  font-size: 3.1cqw;
  letter-spacing: 0.14em;
  white-space: nowrap;
  overflow: hidden;
}

.sb-val-time { left: 21.4%; width: 22.1%; }
.sb-val-loc  { left: 61.3%; width: 25.9%; }



.sb-msg {
  position: absolute;
  left: 15%;
  top: 24.6%;
  width: 70%;
  height: 55%;
  overflow: hidden;
  perspective: 900px;
}

.sb-leaf {
  position: absolute;
  inset: 0;
  padding: 2.6cqw 1.2cqw 1.6cqw;
  transform-origin: 0% 50%;
  transition: transform 0.38s cubic-bezier(0.4, 0, 0.2, 1),
              opacity 0.38s cubic-bezier(0.4, 0, 0.2, 1),
              filter 0.38s;
}

.sb-leaf.sb-out {
  transform: translateX(-42%) rotateY(-32deg);
  opacity: 0;
  filter: brightness(1.7);
}

.sb-leaf.sb-in {
  transform: translateX(34%) rotateY(18deg);
  opacity: 0;
  filter: brightness(1.35);
  transition: none;
}

.sb-leaf p {
  margin: 0 0 0.92em;
  font-size: 4.5cqw;
  line-height: 2.05;
  letter-spacing: 0.06em;
  text-indent: 2em;
  text-align: justify;
  color: var(--sb-ink);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.85);
}

.sb-leaf p:last-child { margin-bottom: 0; }



.sb-ava {
  position: absolute;
  left: 10.8%;
  top: 84.7%;
  width: 13.8%;
  height: 5.8%;
  overflow: hidden;
  border-radius: 4px;
}

.sb-ava-img {
  display: none;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: sepia(0.35) saturate(0.85) brightness(0.9);
}



.sb-say {
  position: absolute;
  left: 29.8%;
  top: 85.2%;
  width: 38.9%;
  height: 3%;
  display: flex;
  align-items: center;
  background: var(--sb-panel2);
  color: var(--sb-gold);
  font-size: 3.5cqw;
  letter-spacing: 0.16em;
  white-space: nowrap;
  overflow: hidden;
}



.sb-next {
  position: absolute;
  left: 73.8%;
  top: 84.5%;
  width: 12.4%;
  height: 3.9%;
  border-radius: 6px;
  outline: none;
}

.sb-next:hover  { background: rgba(207, 192, 115, 0.16); }
.sb-next:active { background: rgba(207, 192, 115, 0.3); }
.sb-next:focus-visible { box-shadow: 0 0 0 2px rgba(207, 192, 115, 0.5); }



.sb-pg {
  position: absolute;
  left: 73.8%;
  top: 88.75%;
  width: 16%;
  height: 2.15%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.2cqw;
  background: var(--sb-panel2);
  font-family: "Courier New", Menlo, Consolas, monospace;
  font-size: 3cqw;
  color: var(--sb-dim);
  white-space: nowrap;
}

.sb-pg-btn {
  cursor: pointer;
  color: var(--sb-gold);
  outline: none;
  padding: 0 0.6cqw;
  line-height: 1;
}
.sb-pg-btn:hover { text-shadow: 0 0 6px rgba(207, 192, 115, 0.65); }
.sb-pg-btn:focus-visible { text-shadow: 0 0 0 #fff, 0 0 4px var(--sb-gold); }

.sb-pg-num {
  color: var(--sb-ink);
  letter-spacing: 0.08em;
}



.sb-raw { display: none; }



@supports not (font-size: 1cqw) {
  .sb-val { font-size: 10.5px; }
  .sb-leaf p { font-size: 15px; }
  .sb-say { font-size: 12px; }
  .sb-pg { font-size: 9.5px; gap: 5px; }
}

@media (prefers-reduced-motion: reduce) {
  .sb-root { animation: none; }
  .sb-leaf { transition: none; }
}

component.script:
(function () {
  'use strict';

  var d = document;
  var D = String.fromCharCode(36);

  function g(id) { return d.getElementById(id); }

  function looksLikeParam(s) {
    if (!s) return true;
    s = s.trim();
    if (!s) return true;
    return s.charAt(0) === D && s.charAt(s.length - 1) === D && s.length > 2;
  }

  function note(msg) {
    try { if (typeof toast === 'function') toast(msg); } catch (e) {}
  }



  var tEl = g('sbTime'), lEl = g('sbLoc'), sEl = g('sbSay');

  if (looksLikeParam(tEl.textContent)) tEl.textContent = '--:--';
  if (looksLikeParam(lEl.textContent)) lEl.textContent = '-----';
  if (looksLikeParam(sEl.textContent)) sEl.textContent = '···';

  var ava = g('sbAva');
  var avaSrc = ava.getAttribute('src') || '';
  if (!looksLikeParam(avaSrc)) {
    ava.style.display = 'block';
    ava.onerror = function () { ava.style.display = 'none'; };
  } else {
    ava.removeAttribute('src');
  }



  var raw = RAWREF();

  function RAWREF() {
    var el = g('sbRaw');
    var t = el ? el.textContent : '';
    t = t.trim();
    if (looksLikeParam(t)) t = '';
    return t;
  }

  if (!raw) {
    raw = '月台尽头的灯又灭了一盏。\n\n末班车驶离之后，这里只剩下海风穿过隧道的声音，混着某种遥远的、规律的叩击。\n\n我数着自己的脚步往回走。第七步的时候，我听见了不该存在的——第二个人的足音。';
  }


  var paras = raw
    .replace(/\|{3,}/g, '\n\n')
    .replace(/\r\n?/g, '\n')
    .split(/\n+/)
    .map(function (s) { return s.replace(/[ \t]+/g, ' ').trim(); })
    .filter(function (s) { return s.length > 0; });

  if (paras.length === 0) {
    paras = ['……'];
  }

  var BUDGET = 92;
  var pieces = [];


  paras.forEach(function (p) {
    if (p.length <= BUDGET) { pieces.push(p); return; }
    var cur = '';
    for (var i = 0; i < p.length; i++) {
      var ch = p.charAt(i);
      cur += ch;
      if (cur.length >= BUDGET * 0.55 && '。！？…；」』'.indexOf(ch) >= 0) {
        pieces.push(cur);
        cur = '';
      }
    }
    if (cur) pieces.push(cur);
  });

  var pages = [];
  var curPage = [];
  var curLen = 0;

  pieces.forEach(function (p) {
    if (curLen > 0 && curLen + p.length > BUDGET) {
      pages.push(curPage);
      curPage = [];
      curLen = 0;
    }
    curPage.push(p);
    curLen += p.length;
  });
  if (curPage.length) pages.push(curPage);
  if (!pages.length) pages = [['……']];

  var idx = 0;
  var busy = false;

  var LEAF = g('sbLeaf');
  var PGNUM = g('sbPgNum');

  function render(i) {
    LEAF.innerHTML = '';
    pages[i].forEach(function (txt) {
      var el = d.createElement('p');
      el.textContent = txt;
      LEAF.appendChild(el);
    });
  }

  function updatePg() {
    PGNUM.textContent = (idx + 1) + ' / ' + pages.length;
  }


  function relieve() {
    var box = LEAF.parentNode;
    var guard = 0;
    while (LEAF.scrollHeight > box.clientHeight + 2 && guard < 8) {
      guard++;
      var ps = LEAF.querySelectorAll('p');
      if (ps.length <= 1) break;
      var last = ps[ps.length - 1];
      var txt = last.textContent;
      LEAF.removeChild(last);
      if (!pages[idx + 1]) pages[idx + 1] = [];
      pages[idx + 1].unshift(txt);
    }
  }

  var REDUCED = false;
  try { REDUCED = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) {}

  function flip(dir) {
    if (busy) return;
    var ni = idx + dir;
    if (ni < 0) { note('已经是第一页'); return; }
    if (ni >= pages.length) { note('已经是最后一页'); return; }
    busy = true;
    idx = ni;

    if (REDUCED) {
      render(idx);
      relieve();
      updatePg();
      busy = false;
      return;
    }

    LEAF.classList.add('sb-out');
    setTimeout(function () {
      render(idx);
      relieve();
      updatePg();
      LEAF.classList.remove('sb-out');
      LEAF.classList.add('sb-in');
      void LEAF.offsetWidth;
      LEAF.classList.remove('sb-in');
      setTimeout(function () { busy = false; }, 380);
    }, 380);
  }



  var PREV = g('sbPrev'), PNEXT = g('sbPgNext'), NEXT = g('sbNext'), ROOT = g('sbRoot');

  NEXT.addEventListener('click', function (e) { e.stopPropagation(); flip(1); });
  PNEXT.addEventListener('click', function (e) { e.stopPropagation(); flip(1); });
  PREV.addEventListener('click', function (e) { e.stopPropagation(); flip(-1); });
  ROOT.addEventListener('click', function () { flip(1); });

  function bindKey(el, dir) {
    el.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        e.stopPropagation();
        flip(dir);
      }
    });
  }
  bindKey(NEXT, 1);
  bindKey(PNEXT, 1);
  bindKey(PREV, -1);



  render(0);
  relieve();
  updatePg();
})();
